package local.lito381.server;
import java.io.*;import java.util.*;
/** Separate actor scene membership from its master's player membership. */
final class NativeCompanionTargets {
 static final String P="local/lito381/server/";
 record Death(Object life,Object bag,NativeCompanionPlacement.State placement,NativeCompanionPlacement.Scene scene,Object pose){}
 static final class Scope implements AutoCloseable {
  final java.lang.ref.WeakReference<ClientSession> caster;final NativePlayerCommit.Binding binding;
  final IdentityHashMap<ClientSession,NativePlayerVitalCompletions.Receipt> receipts=new IdentityHashMap<>();
  final IdentityHashMap<ClientSession,NativePlayerCommit.Binding> bindings=new IdentityHashMap<>();boolean closed,valid=true;
  Scope(NativeAreaMaterialAction.Context c){caster=new java.lang.ref.WeakReference<>(c.pc);binding=c.caster;for(var n:c.npcs.values())if(n.kind()==3&&n.owner()!=c.pc){var owner=(ClientSession)n.owner();if(receipts.containsKey(owner))continue;var receipt=NativePlayerVitalCompletions.reserve(owner);if(receipt==null){valid=false;break;}receipts.put(owner,receipt);bindings.put(owner,c.bindings.get(owner));}}
  boolean nativeRoleOriginalOwns(NativeAreaMaterialAction.Context c,ClientSession owner){var receipt=receipts.get(owner);var frozen=bindings.get(owner);return !closed&&valid&&c.pc==caster.get()&&binding.matches(c.pc)&&receipt!=null&&receipt.pc==owner&&!receipt.released.get()&&frozen!=null&&frozen.matches(owner)&&c.bindings.get(owner)!=null&&c.bindings.get(owner).equals(frozen)&&c.pc.nativePlayerActionLock().isHeldByCurrentThread()&&owner.nativePlayerActionLock().isHeldByCurrentThread();}
  boolean owns(NativeAreaMaterialAction.Context c,ClientSession owner){return NativeCompanionRoleIdentity.owns(this,c,owner);}
public void close(){if(closed)return;closed=true;for(var receipt:receipts.values())receipt.close();receipts.clear();bindings.clear();caster.clear();}
 }
 static Scope scope(NativeAreaMaterialAction.Context c){return c==null?null:(Scope)CombatAccess.field(c,"nativeCompanionTargetScope");}
 static List<ClientSession> owners(List<ClientSession> players,ClientSession caster){
  var result=new ArrayList<>(players);for(var owner:NativeCompanionPlacement.owners(NativeCompanionPlacement.hub(caster),NativeCompanionPlacement.map(caster),NativeCompanionPlacement.instance(caster)))if(!result.contains(owner))result.add(owner);return List.copyOf(result);
 }
 static List<BattleCompanion.Snapshot> snapshots(ClientSession owner,ClientSession caster){var c=NativeAreaMaterialAction.current.get();return NativeCompanionPlacement.inScene(owner,NativeCompanionPlacement.map(caster),NativeCompanionPlacement.instance(caster)).stream().filter(s->c==null||c.npc(s.objectId())).toList();}
 static boolean same(ClientSession caster,ClientSession owner){return NativeCompanionPlacement.world(owner)&&NativeCompanionPlacement.hub(caster)==NativeCompanionPlacement.hub(owner)&&(NativeCompanionPlacement.map(caster)==NativeCompanionPlacement.map(owner)&&NativeCompanionPlacement.instance(caster)==NativeCompanionPlacement.instance(owner)||!snapshots(owner,caster).isEmpty());}
 static int map(ClientSession owner,ClientSession caster){return same(caster,owner)?NativeCompanionPlacement.map(caster):NativeCompanionPlacement.map(owner);}
 static int instance(ClientSession owner,ClientSession caster){return same(caster,owner)?NativeCompanionPlacement.instance(caster):NativeCompanionPlacement.instance(owner);}
 // The native population selectors remain authoritative in these three roots.
 static void cast(ClientSession pc,int skill,NativeSelfCastAction.Task body)throws IOException{var seed=new NativeAreaMaterialAction.Context(pc);try(var scope=new Scope(seed)){if(!scope.valid)return;CombatAccess.set(seed,"nativeCompanionTargetScope",scope);var prior=NativeAreaMaterialAction.current.get();NativeAreaMaterialAction.current.set(seed);try{NativeAreaMaterialAction.nativeCompanionAreaCapturedRun(pc,skill,()->{var context=NativeAreaMaterialAction.current.get();if(!scope.binding.matches(pc)||scope(context)!=scope)return;for(var owner:scope.receipts.keySet())if(!scope.owns(context,owner))return;context.npcs.entrySet().removeIf(e->e.getValue().kind()!=3);body.run();},seed);}finally{if(prior==null)NativeAreaMaterialAction.current.remove();else NativeAreaMaterialAction.current.set(prior);CombatAccess.set(seed,"nativeCompanionTargetScope",null);}}}
 static void capture(NativeAreaMaterialAction.Context c){var parent=NativeAreaMaterialAction.current.get();if(parent!=null&&parent.pc==c.pc&&scope(parent)!=null)CombatAccess.set(c,"nativeCompanionTargetScope",scope(parent));if(!c.phase.equals("WORLD"))return;synchronized(c.hub){
  var players=c.players;
  for(var owner:players){c.bindings.putIfAbsent(owner,NativePlayerCommit.Binding.capture(owner));for(var snap:NativeCompanionPlacement.inScene(owner,c.map,c.instance)){
   var pet=(BattleCompanion)CombatAccess.call(owner,"ownedCompanion","(J)L"+P+"BattleCompanion;",snap.objectId());var state=pet==null?null:NativeCompanionPlacement.state(pet);if(state!=null&&snap.active()&&snap.hp()>0)c.npcs.put(snap.objectId(),new NativeAreaMaterialAction.Npc(3,snap.objectId(),owner,pet,new Object[]{NativeCombatAttacker.companion(owner,pet),state.pose,state.scene}));
  }}
 }}
 static boolean nativeRoleOriginalNpc(NativeAreaMaterialAction.Context c,long id){var n=c.npcs.get(id);if(n!=null&&n.epoch() instanceof Death)return false;if(n==null||!(n.epoch() instanceof Object[] stamp))return (boolean)CombatAccess.call(c,"nativeCompanionOriginalNpc","(J)Z",id);var owner=(ClientSession)n.owner();var pet=(BattleCompanion)n.actor();var h=c.hub;synchronized(h){var state=NativeCompanionPlacement.state(pet);var binding=c.bindings.get(owner);return binding!=null&&binding.matches(owner)&&state!=null&&state.role(owner)&&state.scene==stamp[2]&&state.pose==stamp[1]&&state.scene.at(c.map,c.instance)&&state.scene.alive(h)&&pet.snapshot().active()&&pet.snapshot().hp()>0&&NativeCombatAttacker.alive(owner,(NativeCombatAttacker.Ref)stamp[0]);}}
 // Successful death may publish its own result; it never becomes an admissible live target again.
 static BattleCompanion.Damage finished(BattleCompanion.Damage result,ClientSession owner,BattleCompanion pet){var c=NativeAreaMaterialAction.current.get();if(c==null||!result.diedNow()||pet.snapshot().active()||pet.snapshot().hp()!=0)return result;var n=c.npcs.get(pet.snapshot().objectId());if(n==null||n.kind()!=3||n.owner()!=owner||n.actor()!=pet)return result;var state=NativeCompanionPlacement.state(pet);c.npcs.put(n.id(),new NativeAreaMaterialAction.Npc(n.kind(),n.id(),owner,pet,new Death(NativeCombatAttacker.token((BattleTimedStatus)CombatAccess.field(pet,"timedStatus"),false),CombatAccess.field(pet,"carriedItems"),state,state==null?null:state.scene,state==null?null:state.pose)));return result;}
 static boolean publication(NativeAreaMaterialAction.Context c,long id){var n=c.npcs.get(id);if(n==null||!(n.epoch() instanceof Death proof))return c.npc(id);var owner=(ClientSession)n.owner();var pet=(BattleCompanion)n.actor();var binding=c.bindings.get(owner);var owned=CombatAccess.call(owner,"ownedCompanion","(J)L"+P+"BattleCompanion;",id);if(!c.scene()||binding==null||!NativeCompanionRoleIdentity.actorBinding(binding,owner)||(boolean)CombatAccess.field(owner,"sourceItemDisconnected")||(boolean)CombatAccess.field(c.hub,"nativeStaticMotionClosed")||owned!=null&&owned!=pet||pet.snapshot().objectId()!=id||pet.snapshot().active()||pet.snapshot().hp()!=0||CombatAccess.field(pet,"carriedItems")!=proof.bag()||NativeCombatAttacker.token((BattleTimedStatus)CombatAccess.field(pet,"timedStatus"),false)!=proof.life())return false;var state=NativeCompanionPlacement.state(pet);return proof.placement()==null?state==null&&NativeCompanionPlacement.world(owner)&&NativeCompanionPlacement.map(owner)==c.map&&NativeCompanionPlacement.instance(owner)==c.instance&&NativeCancellationNpcMaterialAction.population(c.hub,c.map,c.instance)==c.population:state==proof.placement()&&state.owner.get()==owner&&state.actor()&&NativeCompanionRoleIdentity.actorBinding(state.master,owner)&&state.scene==proof.scene()&&state.pose==proof.pose()&&state.scene.at(c.map,c.instance)&&state.scene.alive(c.hub);}
 static List<BattleCompanion.Snapshot> areaSnapshots(ClientSession owner){var c=NativeAreaMaterialAction.current.get();return c==null?owner.classicWorldCompanionSnapshots():NativeCompanionPlacement.inScene(owner,c.map,c.instance);}
 static List<ClientSession> damageMembers(ClientSession owner,int ignored,BattleCompanion pet){var state=NativeCompanionPlacement.state(pet);return state==null?(List<ClientSession>)CombatAccess.call(owner,"classicWorldMembers","(I)Ljava/util/List;",ignored):NativeCompanionPlacement.hub(owner).classicWorldMembers(state.scene.map,state.scene.instance);}
 static boolean retained(ClientSession pc){if(NativeLightAction.nativeCompanionOriginalRetainedMaterial(pc))return true;var c=NativeAreaMaterialAction.current.get();var scope=scope(c);return scope!=null&&scope.owns(c,pc)&&NativeLightAction.nativeCompanionOriginalRetainedMaterial(c.pc)&&NativeReturnNatureTransfer.retained(pc);}
 static BattleCompanion.Damage damage(ClientSession owner,BattleCompanion pet,int amount)throws IOException{var producer=NativeLightAction.currentMaterialProducer();if(producer==null||producer==owner||NativeAreaMaterialAction.current.get()==null||scope(NativeAreaMaterialAction.current.get())!=null)return NativeSummonTerminalLifecycle.combatDamage(owner,pet,amount);var before=pet.snapshot();var result=new BattleCompanion.Damage[]{new BattleCompanion.Damage(before,before,0,false)};NativeLightAction.commitPair(producer,owner,()->result[0]=NativeSummonTerminalLifecycle.combatDamage(owner,pet,amount));return result[0];}
 static boolean npc(NativeAreaMaterialAction.Context c,long id){return NativeCompanionRoleIdentity.npc(c,id);}
private NativeCompanionTargets(){}
}
